class Solution:
    def topKFrequent(self, nums: list[int], k: int) -> list[int]:
        unique = []
        for x in nums:
            if x not in unique:
                unique.append(x)
        freq = []
        for x in unique:
            freq.append((sum(1 for y in nums if y == x), x))
        freq.sort(reverse=True)
        return [x for _, x in freq[:k]]

