class Solution:
    def topKFrequent(self, nums: list[int], k: int) -> list[int]:
        counts = {}
        for x in nums:
            counts[x] = counts.get(x, 0) + 1
        items = sorted(counts, key=lambda x: counts[x], reverse=True)
        return items[:k]

