class Solution:
    def topKFrequent(self, nums: list[int], k: int) -> list[int]:
        counts = {}
        for x in nums:
            counts[x] = counts.get(x, 0) + 1
        buckets = [[] for _ in range(len(nums) + 1)]
        for x, c in counts.items():
            buckets[c].append(x)
        ans = []
        for c in range(len(buckets) - 1, 0, -1):
            for x in buckets[c]:
                ans.append(x)
                if len(ans) == k:
                    return ans
        return ans

